function suffixAlarm(words, stream) {
  const alarms = [];
  for (let end = 0; end < stream.length; end++) {
    let hit = false;
    for (const word of words) {
      const start = end + 1 - word.length;
      if (start >= 0 && stream.startsWith(word, start)) {
        hit = true;
        break;
      }
    }
    alarms.push(hit);
  }
  return alarms;
}

function suffixAlarm(words, stream) {
  let longest = 0;
  let total = 0;
  for (const word of words) {
    longest = Math.max(longest, word.length);
    total += word.length;
  }
  const child = new Int32Array(26 * (total + 1));
  const terminal = new Uint8Array(total + 1);
  let nodes = 1;
  for (const word of words) {
    let at = 0;
    for (let i = word.length - 1; i >= 0; i--) {
      const slot = at * 26 + word.charCodeAt(i) - 97;
      if (child[slot] === 0) child[slot] = nodes++;
      at = child[slot];
    }
    terminal[at] = 1;
  }
  const alarms = [];
  for (let end = 0; end < stream.length; end++) {
    let at = 0;
    let hit = false;
    for (let i = end; i >= 0 && i > end - longest; i--) {
      at = child[at * 26 + stream.charCodeAt(i) - 97];
      if (at === 0) break;
      if (terminal[at] === 1) {
        hit = true;
        break;
      }
    }
    alarms.push(hit);
  }
  return alarms;
}
